#!/usr/bin/env bash
# Show that the SBOM verifier reproduces the audit's known gaps in the FROZEN v0.3.2 SBOMs, and that SBOMs
# generated by this tooling from the same archives pass it. Read-only on the frozen evidence.
#
#   FROZEN_EVIDENCE_DIR=<scratchpad holding native-release-evidence/, macos-agentic-apps-v0.3.2/, r0-audit/> \
#   packaging/sbom/check_frozen_gaps.sh [--out DIR]
#
# Inputs (all read-only): native-release-evidence/{macos,windows}/sbom.cdx.json (the frozen, lock-derived SBOMs),
# macos-agentic-apps-v0.3.2/evidence-plan/{archive_listing.txt,sidecar.orig}, r0-audit/licences/windows_frozen_{pkg_listing,pyz_modules}.txt.
# Version/metadata oracle: the new hash locks (== the 21 wheels the frozen CI run built) via wheels downloaded
# with --require-hashes (macOS wheels from the local wheelhouse, Windows wheels downloaded for win_amd64).
# Needs: uv, network for the Windows wheels, packaging/wheelhouse built (build-wheelhouse.sh).
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"; PK="$(cd "$HERE/.." && pwd)"
[ -n "${FROZEN_EVIDENCE_DIR:-}" ] || { echo "set FROZEN_EVIDENCE_DIR"; exit 2; }
F="$FROZEN_EVIDENCE_DIR"; OUT="${2:-$(mktemp -d)}"; [ "${1:-}" = "--out" ] || OUT="$(mktemp -d)"; mkdir -p "$OUT"
. "$PK/toolchain.env"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
uv venv --python "$PYTHON_VERSION" "$TMP/v" >/dev/null; PY="$TMP/v/bin/python"
uv pip install --python "$PY" --require-hashes --no-deps -r "$PK/locks/build-tools-macos.lock" >/dev/null   # PyInstaller reader (macOS lock: the tool runs on this Mac)
uv pip install --python "$PY" --require-hashes --no-deps -r "$PK/locks/pip.lock" >/dev/null           # pip: to download the Windows wheels
mkdir -p "$TMP/win"
"$PY" -m pip download -q --platform win_amd64 --python-version 3.12 --implementation cp --abi cp312 --only-binary=:all: --require-hashes --no-deps \
    -r "$PK/locks/requirements-windows.lock" -d "$TMP/win" 2>"$OUT/win-download.err" || echo "(windows wheel download failed: see $OUT/win-download.err)"
# the first-party wheels: the set git-pins.json defines (+ agentic-os), not a hand-written list (D-NEW-1)
for w in $("$PY" -I "$PK/tools/first_party.py" wheels --wheelhouse "$PK/wheelhouse" --lock "$PK/locks/requirements-macos.lock" | tr -d '\r'); do cp "$PK/wheelhouse/$w" "$TMP/win/"; done
TOOLS="$HERE/testdata/build-tools-inventory-macos.json"
run() { # name expected(0|1) args...
  local name="$1" want="$2"; shift 2
  "$PY" -I "$HERE/verify_sbom.py" "$@" > "$OUT/$name.txt" 2>&1; local rc=$?
  printf '%-52s verifier exit %s (expected %s)  %s\n' "$name" "$rc" "$want" "$(tail -1 "$OUT/$name.txt")"
  [ "$rc" = "$want" ] || echo "   UNEXPECTED"
}
M="$F/macos-agentic-apps-v0.3.2/evidence-plan"
echo "1) frozen macOS SBOM vs frozen archive LISTING (+ facts for what a listing cannot show)"
run frozen-macos-sbom-vs-listing 1 --sbom "$F/native-release-evidence/macos/sbom.cdx.json" --pkg-listing "$M/archive_listing.txt" \
    --wheelhouse "$PK/wheelhouse" --inventory-json "$TOOLS" --facts "$HERE/testdata/frozen-v0.3.2-macos-facts.json"
echo "2) frozen macOS SBOM vs the frozen sidecar EXECUTABLE (bytes: no facts needed)"
[ -f "$M/sidecar.orig" ] && run frozen-macos-sbom-vs-executable 1 --sbom "$F/native-release-evidence/macos/sbom.cdx.json" --sidecar "$M/sidecar.orig" \
    --wheelhouse "$PK/wheelhouse" --inventory-json "$TOOLS"
echo "3) frozen Windows SBOM vs the Windows frozen archive listing"
run frozen-windows-sbom-vs-listing 1 --sbom "$F/native-release-evidence/windows/sbom.cdx.json" --pkg-listing "$F/r0-audit/licences/windows_frozen_pkg_listing.txt" \
    --pyz-listing "$F/r0-audit/licences/windows_frozen_pyz_modules.txt" --wheelhouse "$TMP/win" --inventory-json "$TOOLS" \
    --facts "$HERE/testdata/frozen-v0.3.2-windows-facts.json"
echo "4) SBOMs generated by this tooling from the same archives pass the verifier"
"$PY" -I "$HERE/generate_sbom.py" --pkg-listing "$M/archive_listing.txt" --wheelhouse "$PK/wheelhouse" --inventory-json "$TOOLS" \
    --facts "$HERE/testdata/frozen-v0.3.2-macos-facts.json" --git-pins "$PK/git-pins.json" --out "$OUT/generated-macos" > "$OUT/generate-macos.txt" 2>&1
run generated-macos-sbom-vs-listing 0 --sbom "$OUT/generated-macos/sbom.cdx.json" --pkg-listing "$M/archive_listing.txt" --wheelhouse "$PK/wheelhouse" \
    --inventory-json "$TOOLS" --facts "$HERE/testdata/frozen-v0.3.2-macos-facts.json"
"$PY" -I "$HERE/generate_sbom.py" --pkg-listing "$F/r0-audit/licences/windows_frozen_pkg_listing.txt" --pyz-listing "$F/r0-audit/licences/windows_frozen_pyz_modules.txt" \
    --wheelhouse "$TMP/win" --inventory-json "$TOOLS" --facts "$HERE/testdata/frozen-v0.3.2-windows-facts.json" --git-pins "$PK/git-pins.json" \
    --out "$OUT/generated-windows" > "$OUT/generate-windows.txt" 2>&1
run generated-windows-sbom-vs-listing 0 --sbom "$OUT/generated-windows/sbom.cdx.json" --pkg-listing "$F/r0-audit/licences/windows_frozen_pkg_listing.txt" \
    --pyz-listing "$F/r0-audit/licences/windows_frozen_pyz_modules.txt" --wheelhouse "$TMP/win" --inventory-json "$TOOLS" \
    --facts "$HERE/testdata/frozen-v0.3.2-windows-facts.json"
echo "outputs in $OUT"
